const touchpoints = $input.all();
const userJourneys = {};
touchpoints.forEach(tp => {
  if (!userJourneys[tp.json.user_id]) userJourneys[tp.json.user_id] = [];
  userJourneys[tp.json.user_id].push(tp.json);
});

const attributed = Object.entries(userJourneys).map(([userId, journey]) => {
  const sortedJourney = journey.sort((a,b) => new Date(a.timestamp) - new Date(b.timestamp));
  const firstTouch = sortedJourney[0];
  const lastTouch = sortedJourney[sortedJourney.length - 1];
  const linearValue = (lastTouch.conversion_value || 0) / sortedJourney.length;
  return {
    json: {
      user_id: userId,
      first_touch_source: firstTouch.touchpoint_source,
      last_touch_source: lastTouch.touchpoint_source,
      touchpoint_count: sortedJourney.length,
      linear_attribution_value: linearValue,
      conversion_value: lastTouch.conversion_value || 0
    }
  };
});
return attributed;
